import math
from decimal import Decimal, getcontext

getcontext().prec = 80

def cp_upper_decimal(n, k, conf):
    alpha = Decimal(1) - Decimal(str(conf))
    log_comb = [Decimal(math.comb(n, j)).ln() for j in range(k+1)]
    def cdf(p):
        lp = p.ln(); lq = (1 - p).ln()
        return sum((lc + j*lp + (n-j)*lq).exp() for j, lc in enumerate(log_comb))
    lo, hi = Decimal(0), Decimal(1)
    for _ in range(300):
        mid = (lo + hi) / 2
        if cdf(mid) > alpha:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2

cases = [(5,0),(5,2),(5,4),(10,1),(10,5),(20,3),(100,3),(100,50),(1000,10),(10000,0),(10000,100),(10000,5000)]
for conf in (0.9, 0.95, 0.999):
    for n, k in cases:
        p = cp_upper_decimal(n, k, conf)
        print(f"({conf}, {n}, {k}, {float(p)!r}),")
